import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Styles","description":"","frontmatter":{},"headers":[],"relativePath":"guide/styles.md","filePath":"guide/styles.md"}'),s={name:"guide/styles.md"};function d(n,e,l,i,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="styles" tabindex="-1">Styles <a class="header-anchor" href="#styles" aria-label="Permalink to &quot;Styles&quot;">​</a></h1><p>Three styles, after three games. Each sounding character (letter, digit or other symbol) plays one sound; spaces and punctuation are silences.</p><h2 id="beep" tabindex="-1">Beep <a class="header-anchor" href="#beep" aria-label="Permalink to &quot;Beep&quot;">​</a></h2><p><em>One beep for every letter</em>, like <strong>Undertale</strong>. The same short square-wave beep for every character. With variation at 0 every beep has the same pitch.</p><ul><li>Sound identifier: variant <code>0</code>.</li></ul><h2 id="grunt" tabindex="-1">Grunt <a class="header-anchor" href="#grunt" aria-label="Permalink to &quot;Grunt&quot;">​</a></h2><p><em>A few grunts for each character</em>, like <strong>Banjo-Kazooie</strong>. The voice has four grunts, different in pitch, length and timbre; each character plays one of them, chosen pseudo-randomly but deterministically, and never the same grunt twice in a row.</p><ul><li>Sound identifier: variant <code>0</code>–<code>3</code>, the grunt that plays.</li></ul><h2 id="alphabet" tabindex="-1">Alphabet <a class="header-anchor" href="#alphabet" aria-label="Permalink to &quot;Alphabet&quot;">​</a></h2><p><em>A sound for every letter of the alphabet</em>, like <strong>Animal Crossing</strong>. Each letter is a short syllable: an optional consonant attack (filtered noise) followed by a vowel made with three formants, at almost the same pitch for every letter (within ±1 semitone), so letters differ by timbre, not by note.</p><ul><li>The letters <code>a e i o u</code> sound as the Italian vowels.</li><li>Consonants use the vowel of their English name (<code>b</code> → &quot;bi&quot;, <code>f</code> → &quot;e&quot;, <code>q</code> → &quot;u&quot;).</li><li>Accented letters fold to their base letter (<code>è</code> → <code>e</code>, <code>ñ</code> → <code>n</code>).</li><li>Digits and other symbols share one neutral sound.</li><li>Sound identifier: variant <code>0</code>–<code>25</code> for <code>a</code>–<code>z</code>, <code>26</code> for the neutral sound.</li></ul><h2 id="pauses" tabindex="-1">Pauses <a class="header-anchor" href="#pauses" aria-label="Permalink to &quot;Pauses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Character</th><th>Silence</th></tr></thead><tbody><tr><td>space, tab</td><td>1 slot</td></tr><tr><td><code>,</code> <code>;</code> <code>:</code></td><td>2 slots</td></tr><tr><td><code>.</code> <code>!</code> <code>?</code> <code>…</code>, new line</td><td>4 slots</td></tr></tbody></table><p>A slot is <code>1 / speed</code> seconds; see <a href="./concepts#voice">Concepts</a>.</p><p>The exact tables (frequencies, formants, envelopes) are in the <a href="https://github.com/basteez/mumble-speech/blob/main/specs/design.md#5-styles" target="_blank" rel="noreferrer">design document</a>.</p>',15)])])}const b=t(s,[["render",d]]);export{p as __pageData,b as default};
